def verify_isbn(isbn: str) -> str:
    # Remove hyphens and validate format
    parts = isbn.split('-')
    if len(parts) != 5:
        # Invalid format, but proceed to check if possible
        # For now, assume the input is in the expected format
        pass

    # Extract the numeric part (first 10 characters without hyphens)
    isbn_no_hyphens = isbn.replace('-', '')
    if len(isbn_no_hyphens) != 10:
        # Invalid length
        return isbn  # Or handle error appropriately

    # Check if all characters except possibly the last are digits
    if not all(c.isdigit() for c in isbn_no_hyphens[:9]):
        # Invalid characters
        return isbn  # Or handle error appropriately

    # Calculate the checksum
    checksum = 0
    for i in range(9):
        checksum += (i + 1) * int(isbn_no_hyphens[i])

    # The last character is the check digit
    last_char = isbn_no_hyphens[9]

    if last_char == 'X':
        expected = checksum % 11
        if expected == 10:
            return "Right"
        else:
            # The correct check digit is expected
            corrected = isbn_no_hyphens[:9] + str(expected)
            # Reinsert hyphens in the same positions
            corrected_parts = corrected.split('')
            if len(corrected_parts) == 10:
                corrected_isbn = corrected_parts[0] + '-' + corrected_parts[1:4].join('') + '-' + corrected_parts[4:9].join('') + '-' + corrected_parts[9]
            else:
                corrected_isbn = corrected
            return corrected_isbn
    elif last_char.isdigit():
        expected = checksum % 11
        if int(last_char) == expected:
            return "Right"
        else:
            corrected = isbn_no_hyphens[:9] + str(expected)
            corrected_parts = list(corrected)
            if len(corrected_parts) == 10:
