def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Count the number of chatting pairs that can be separated by a horizontal aisle at each row position
    # A horizontal aisle between row i and i+1 (1 <= i <= M-1) separates pairs where one is in row <= i and the other in row > i
    horizontal_aisles = [0] * (M - 1)  # index 0 corresponds to aisle after row 1, etc.

    # Count the number of chatting pairs that can be separated by a vertical aisle at each column position
    vertical_aisles = [0] * (N - 1)  # index 0 corresponds to aisle after column 1, etc.

    # For each chatting pair, update the horizontal and vertical aisle counts
    for x1, y1, x2, y2 in chatting_pairs:
        # Normalize x1 and x2 such that x1 < x2
        if x1 > x2:
            x1, x2 = x2, x1
        # Normalize y1 and y2 such that y1 < y2
        if y1 > y2:
            y1, y2 = y2, y1

        # If x1 != x2, then the pair can be separated by a horizontal aisle between x1 and x2-1
        if x1 != x2:
            for i in range(x1 - 1, x2 - 1):
                horizontal_aisles[i] += 1

        # If y1 != y2, then the pair can be separated by a vertical aisle between y1 and y2-1
        if y1 != y2:
            for j in range(y1 - 1, y2 - 1):
                vertical_aisles[j] += 1

    # Select the best K horizontal aisles and L vertical aisles
    # Sort by the count in descending order, and if tie, by index in ascending order
    def get_best_aisles(aisles, k):
        if k <= 0:
            return ''
        # Create list of (count, index) pairs
        pairs = [(aisles[i], i + 1) for i in range(len(aisles))]
        # Sort by count descending, then by index ascending
        pairs.sort(key=lambda x: (-x[0], x[1]))
        # Take top k
        best = [str(x[1]) for x in pairs[:k]]
        return ' '.join(best)

    horiz_result = get_best_aisles(horizontal_aisles, K)
    vert_result = get_best_aisles(vertical_aisles, L)

    return (horiz_result, vert_result)
