    if M == 1:
        horizontal = []
    else:
        horizontal = [0] * (M + 1)
    if N == 1:
        vertical = [0] * (N + 1)
    else:
        vertical = [0] * (N + 1)

    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        min_row, max_row = min(x1, x2), max(x1, x2)
        min_col, max_col = min(y1, y2), max(y1, y2)

        if min_row < max_row and M >= 2:
            for i in range(min_row, max_row):
                horizontal[i] += 1

        if min_col < max_col and N >= 2:
            for j in range(min_col, max_col):
                vertical[j] += 1

    def select_positions(counts, max_position, num_to_select):
        if num_to_select == 0 or max_position < 1:
            return []
        items = [(count, idx) for idx, count in enumerate(counts) if idx != 0]
        items.sort(key=lambda x: (-x[0], x[1]))
        selected = []
        for count, idx in items:
            if len(selected) == num_to_select:
                break
            selected.append(idx)
            if count < 0:
                break
        selected.sort()
        return selected

    horizontal_result = select_positions(horizontal, M - 1, K)
    vertical_result = select_positions(vertical, N - 1, L)

    row_str = ' '.join(map(str, horizontal_result)) if horizontal_result else ''
    col_str = ' '.join(map(str, vertical_result)) if vertical_result else ''

    return row_str, col_str

