def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    degree = n
    for coeff in coeffs:
        if coeff == 0:
            degree -= 1
            continue

        if degree == 0:
            # Constant term
            if terms:
                if coeff > 0:
                    terms.append(f"+{abs(coeff)}")
                else:
                    terms.append(f"-{abs(coeff)}")
            else:
                terms.append(str(coeff))
        else:
            # Coefficient part
            abs_coeff = abs(coeff)
            if degree == 1 and abs_coeff == 1:
                coeff_part = ""
            else:
                coeff_part = str(abs_coeff)

            # Variable part
            if degree == 1:
                var_part = "x"
            elif degree > 1:
                var_part = f"x^{degree}"
            else:
                var_part = ""

            if terms:
                if coeff > 0:
                    terms.append(f"+{coeff_part}{var_part}")
                else:
                    terms.append(f"-{coeff_part}{var_part}")
            else:
                if coeff < 0:
                    terms.append(f"-{coeff_part}{var_part}")
                else:
                    terms.append(f"{coeff_part}{var_part}")

        degree -= 1

    if not terms:
        return "0"

    return "".join(terms)
