def generate_numbers(n, rules) -> int:
    from collections import deque

    # Create a mapping from digit to list of possible transformations
    transform_map = {}
    for x, y in rules:
        if x not in transform_map:
            transform_map[x] = []
        transform_map[x].append(y)

    def get_transformations(num_str):
        """Generate all possible transformations of the given number string"""
        transformations = []
        for i in range(len(num_str)):
            digit = int(num_str[i])
            if digit in transform_map:
                for new_digit in transform_map[digit]:
                    new_num_str = num_str[:i] + str(new_digit) + num_str[i+1:]
                    # Avoid leading zeros unless the number is exactly "0"
                    if new_num_str[0] != '0' or len(new_num_str) == 1:
                        transformations.append(new_num_str)
            # Also keep the original digit (identity transformation implicitly handled by starting from original)
        return transformations

    start_str = str(n)
    visited = set()
    queue = deque()
    visited.add(start_str)
    queue.append(start_str)

    while queue:
        current = queue.popleft()
        for transformed in get_transformations(current):
            if transformed not in visited:
                visited.add(transformed)
                queue.append(transformed)

    return len(visited)
