def minimum_students_to_leave(heights):
    if not heights:
        return 0

    n = len(heights)

    # Compute Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Compute Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum length of a choir formation (increasing then decreasing)
    # The peak can be at any position i, where the formation is lis[i] + lds[i] - 1
    max_choir_length = max(lis[i] + lds[i] - 1 for i in range(n))

    # Minimum students to leave
    return n - max_choir_length
